/**
 * ARSIP FOTO & MEMORI KENANGAN OSIS SMKN 1 TARUMAJAYA
 * Authentic Chalkboard + Catenary Rope + Natural Polaroid Hang
 */

let currentUser = window.currentUser;
const arsipData  = window.arsipData || [];
const track      = document.getElementById("polaroid-track");
const lightbox   = document.getElementById("chalk-lightbox");

/* Natural rest angles for each polaroid */
const naturalAngles = [-3.8, 2.4, -2.0, 3.6, -1.6, 2.9, -3.2, 1.8, -2.6, 3.2, -1.4, 2.1];

/* ─────────────────────────────────────────────────────────
   CATENARY ROPE SVG  —  drawn on a canvas that spans the
   full width of .rope-stage and sags a natural ~24px.
   ───────────────────────────────────────────────────────── */
function drawRopeSVG() {
    const stage    = document.querySelector(".rope-stage");
    const existing = document.getElementById("rope-svg");
    if (!stage) return;
    if (existing) existing.remove();

    const W    = stage.offsetWidth;
    const H    = 70;        // svg canvas height
    const PAD  = 32;        // nail x offset from edges
    const SAG  = 28;        // how far the rope sags below nail level
    const NY   = 20;        // nail y position inside svg
    const NAIL_R = 9;       // nail radius

    /* Catenary-like cubic bezier:
       Start at left-nail, control points push down to create sag,
       end at right-nail.                                        */
    const x1 = PAD, y1 = NY + 2;
    const x2 = W - PAD, y2 = NY + 2;
    const cx  = W / 2;
    const cy  = NY + SAG;

    // Build SVG string
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("id", "rope-svg");
    svg.setAttribute("width", "100%");
    svg.setAttribute("height", H);
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.setAttribute("preserveAspectRatio", "none");
    svg.style.cssText = "display:block;overflow:visible;position:relative;z-index:20;margin-bottom:-18px;";

    svg.innerHTML = `
      <defs>
        <!-- Jute rope repeating stripe pattern -->
        <pattern id="jutePattern" x="0" y="0" width="14" height="10" patternUnits="userSpaceOnUse" patternTransform="rotate(50)">
          <rect width="14" height="10" fill="#7c4a1b"/>
          <rect x="0"  width="3.5" height="10" fill="#522f0f" opacity="0.9"/>
          <rect x="3.5" width="3"   height="10" fill="#b27a3e" opacity="0.85"/>
          <rect x="6.5" width="3"   height="10" fill="#e8c47a" opacity="0.65"/>
          <rect x="9.5" width="2"   height="10" fill="#b27a3e" opacity="0.75"/>
          <rect x="11.5" width="2.5" height="10" fill="#522f0f" opacity="0.9"/>
        </pattern>

        <!-- Rope stroke: filled path with jute pattern -->
        <filter id="ropeGlow">
          <feGaussianBlur in="SourceAlpha" stdDeviation="2.5" result="blur"/>
          <feFlood flood-color="#000" flood-opacity="0.65" result="col"/>
          <feComposite in="col" in2="blur" operator="in" result="shadow"/>
          <feMerge><feMergeNode in="shadow"/><feMergeNode in="SourceGraphic"/></feMerge>
        </filter>
        <radialGradient id="nailGrad" cx="38%" cy="35%" r="58%">
          <stop offset="0%"   stop-color="#fff9c4"/>
          <stop offset="40%"  stop-color="#d97706"/>
          <stop offset="78%"  stop-color="#92400e"/>
          <stop offset="100%" stop-color="#451a03"/>
        </radialGradient>
      </defs>

      <!-- Drop shadow for the sag rope -->
      <path
        d="M ${x1} ${y1} Q ${cx} ${cy + 8} ${x2} ${y2}"
        fill="none"
        stroke="rgba(0,0,0,0.5)"
        stroke-width="10"
        stroke-linecap="round"
        filter="url(#ropeGlow)"
        transform="translate(0,4)"
      />

      <!-- Rope body — thick path, filled with jute pattern -->
      <path
        id="rope-path"
        d="M ${x1} ${y1} Q ${cx} ${cy} ${x2} ${y2}"
        fill="none"
        stroke="url(#jutePattern)"
        stroke-width="9"
        stroke-linecap="round"
        filter="url(#ropeGlow)"
      />

      <!-- Rope highlight (top sheen) -->
      <path
        d="M ${x1} ${y1} Q ${cx} ${cy} ${x2} ${y2}"
        fill="none"
        stroke="rgba(255,255,255,0.22)"
        stroke-width="2.5"
        stroke-linecap="round"
        transform="translate(0,-1.5)"
      />

      <!-- LEFT NAIL -->
      <circle cx="${x1}" cy="${NY}" r="${NAIL_R}"   fill="url(#nailGrad)"/>
      <circle cx="${x1}" cy="${NY}" r="${NAIL_R+3}"  fill="none" stroke="rgba(80,40,10,0.7)" stroke-width="2.5"/>
      <circle cx="${x1 - 2}" cy="${NY - 3}" r="2.5" fill="rgba(255,255,255,0.65)"/>

      <!-- RIGHT NAIL -->
      <circle cx="${x2}" cy="${NY}" r="${NAIL_R}"   fill="url(#nailGrad)"/>
      <circle cx="${x2}" cy="${NY}" r="${NAIL_R+3}"  fill="none" stroke="rgba(80,40,10,0.7)" stroke-width="2.5"/>
      <circle cx="${x2 - 2}" cy="${NY - 3}" r="2.5" fill="rgba(255,255,255,0.65)"/>
    `;

    stage.insertBefore(svg, stage.querySelector(".arsip-track"));
}

/* Re-draw rope on window resize */
window.addEventListener("resize", drawRopeSVG);


/* ─────────────────────────────────────────────────────────
   RENDER POLAROID CARDS
   ───────────────────────────────────────────────────────── */
function renderArsip() {
    if (!track) return;
    track.innerHTML = "";

    if (!arsipData.length) {
        track.innerHTML = `
            <div class="w-full flex flex-col items-center justify-center py-20 text-center">
                <div class="w-20 h-20 rounded-3xl bg-white/5 border-2 border-dashed border-white/30 flex items-center justify-center text-4xl mb-4">
                    📷
                </div>
                <h3 class="chalk-font-hand text-3xl font-bold text-white chalk-text">Papan Tulis Ini Masih Kosong</h3>
                <p class="chalk-font-sub text-lg text-slate-300 mt-2 max-w-md">
                    Belum ada momen yang digantungkan. Pengurus dapat memulai dengan menambahkan kenangan pertama!
                </p>
            </div>
        `;
        return;
    }

    arsipData.forEach((item, idx) => {
        const card = document.createElement("div");
        card.className = "polaroid wind group cursor-pointer";

        const angle = naturalAngles[idx % naturalAngles.length];
        card.style.setProperty("--rot-angle", `${angle}deg`);
        card.style.animationDelay    = `${(idx % 7) * 0.65}s`;
        card.style.animationDuration = `${4.2 + (idx % 4) * 0.7}s`;

        /* ── Clothespin SVG  ──
           Two wooden prongs clamped around the rope + a metal spring.
           Drawn wider & more natural than before.                     */
        const pid = `p${idx}`;
        card.innerHTML = `
            <!-- Realistic wooden clothespin -->
            <div class="clothespin-wrap" aria-hidden="true">
              <svg width="26" height="56" viewBox="0 0 26 56" fill="none" xmlns="http://www.w3.org/2000/svg">
                <defs>
                  <linearGradient id="wd_${pid}" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%"   stop-color="#5c2e0a"/>
                    <stop offset="20%"  stop-color="#a0632b"/>
                    <stop offset="50%"  stop-color="#d9a05a"/>
                    <stop offset="80%"  stop-color="#a0632b"/>
                    <stop offset="100%" stop-color="#5c2e0a"/>
                  </linearGradient>
                  <linearGradient id="wd2_${pid}" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%"   stop-color="#3d1e06"/>
                    <stop offset="30%"  stop-color="#7a4518"/>
                    <stop offset="60%"  stop-color="#b07238"/>
                    <stop offset="100%" stop-color="#3d1e06"/>
                  </linearGradient>
                  <linearGradient id="spring_${pid}" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%"   stop-color="#e2e8f0"/>
                    <stop offset="50%"  stop-color="#64748b"/>
                    <stop offset="100%" stop-color="#1e293b"/>
                  </linearGradient>
                </defs>

                <!-- Back prong (darker, behind) -->
                <path d="M3 1 C3 1 10 0 10 0 L10 24 L10 32 L10 55 C10 55 3 55 3 54 Z"
                      fill="url(#wd2_${pid})" stroke="#2a0f03" stroke-width="0.5"/>

                <!-- Front prong -->
                <path d="M5 0 C5 0 23 0.5 23 1 C23.5 1.5 24 2.5 24 3 L24 22 L19 24.5 L19 29 L24 31.5 L24 54 C24 54.5 23 55.5 22 55.5 L5 55 C4 55 3.5 54 3.5 53 L3.5 2 C3.5 1 4.2 0.2 5 0 Z"
                      fill="url(#wd_${pid})" stroke="#3d1e06" stroke-width="0.6"/>

                <!-- Wood grain lines -->
                <line x1="9"  y1="2" x2="9"  y2="53" stroke="#f5d9a0" stroke-width="0.5" opacity="0.5" stroke-dasharray="5 4 9 3"/>
                <line x1="16" y1="2" x2="16" y2="53" stroke="#3d1e06" stroke-width="0.5" opacity="0.4" stroke-dasharray="7 5 11 3"/>

                <!-- Spring wire top arm -->
                <path d="M11 15 C13 17 15 18 17 20" stroke="url(#spring_${pid})" stroke-width="2" stroke-linecap="round"/>
                <!-- Spring coil body -->
                <rect x="9" y="22" width="10" height="8" rx="2.5" fill="url(#spring_${pid})" stroke="#475569" stroke-width="0.6"/>
                <ellipse cx="14" cy="26" rx="3" ry="1.4" fill="rgba(255,255,255,0.75)"/>
                <!-- Spring wire bottom arm -->
                <path d="M17 30 C15 32 13 33 11 35" stroke="url(#spring_${pid})" stroke-width="2" stroke-linecap="round"/>

                <!-- Top highlight on front prong -->
                <path d="M6 1.5 L21 2" stroke="rgba(255,255,255,0.35)" stroke-width="1" stroke-linecap="round"/>
              </svg>
            </div>

            <!-- Delete checkbox (hidden until delete-mode) -->
            <label class="delete-checkbox-wrapper hidden absolute top-3 left-3 z-30 cursor-pointer">
                <input type="checkbox" class="delete-checkbox peer hidden" data-id="${item.id}">
                <div class="w-7 h-7 rounded-full bg-white/95 border-2 border-rose-500 shadow-md flex items-center justify-center transition-all duration-200 peer-checked:bg-rose-600 peer-checked:scale-110">
                    <svg class="w-4 h-4 text-white opacity-0 peer-checked:opacity-100 transition" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M5 13l4 4L19 7"/>
                    </svg>
                </div>
            </label>

            <!-- Photo area -->
            <div class="polaroid-img-wrapper">
                <img src="/storage/arsip/${item.foto}" alt="${item.judul}" draggable="false" loading="lazy">
            </div>

            <!-- Caption area (like a real polaroid's white strip) -->
            <div class="mt-3 text-center px-1">
                <div class="chalk-font-hand text-[1.4rem] font-bold text-slate-800 leading-snug">
                    ${item.judul}
                </div>
                <div class="chalk-font-sub text-[0.78rem] text-slate-500 mt-0.5 line-clamp-2 leading-relaxed">
                    ${item.caption || 'Momen tak terlupakan bersama keluarga besar OSIS.'}
                </div>
                <div class="mt-2 chalk-font-sub text-[0.7rem] text-rose-800/60 tracking-widest uppercase font-semibold">
                    ${item.tahun}
                </div>
            </div>
        `;

        card.addEventListener("click", (evt) => {
            if (deleteMode) return;
            if (evt.target.closest(".delete-checkbox-wrapper")) return;
            openLightbox(item);
        });

        track.appendChild(card);
    });

    /* Draw the rope AFTER cards are in the DOM */
    requestAnimationFrame(() => {
        drawRopeSVG();
    });
}


/* ─────────────────────────────────────────────────────────
   LIGHTBOX
   ───────────────────────────────────────────────────────── */
function openLightbox(item) {
    if (!lightbox) return;
    const imgEl      = document.getElementById("lightbox-img");
    const titleEl    = document.getElementById("lightbox-title");
    const captionEl  = document.getElementById("lightbox-caption");
    const yearEl     = document.getElementById("lightbox-year");
    const downloadEl = document.getElementById("lightbox-download");

    if (imgEl)      imgEl.src = `/storage/arsip/${item.foto}`;
    if (titleEl)    titleEl.textContent   = item.judul;
    if (captionEl)  captionEl.textContent = item.caption || "Momen tak terlupakan bersama keluarga besar OSIS.";
    if (yearEl)     yearEl.textContent    = `Periode ${item.tahun}`;
    if (downloadEl) {
        downloadEl.href     = `/storage/arsip/${item.foto}`;
        downloadEl.download = `${item.judul}.jpg`;
    }

    lightbox.classList.remove("hidden");
    requestAnimationFrame(() => lightbox.classList.add("is-open"));
    document.body.style.overflow = "hidden";
}

function closeLightbox() {
    if (!lightbox) return;
    lightbox.classList.remove("is-open");
    setTimeout(() => lightbox.classList.add("hidden"), 300);
    document.body.style.overflow = "";
}

if (lightbox) {
    lightbox.addEventListener("click", (e) => {
        if (e.target === lightbox || e.target.closest("#lightbox-close-btn")) {
            closeLightbox();
        }
    });
    window.addEventListener("keydown", (e) => {
        if (e.key === "Escape") closeLightbox();
    });
}


/* ─────────────────────────────────────────────────────────
   DRAG SCROLL
   ───────────────────────────────────────────────────────── */
let startX, scrollLeft, isDown = false;
if (track) {
    track.addEventListener("mousedown", (e) => {
        if (e.target.closest(".delete-checkbox-wrapper")) return;
        isDown = true;
        startX = e.pageX - track.offsetLeft;
        scrollLeft = track.scrollLeft;
    });
    track.addEventListener("mouseleave", () => { isDown = false; });
    track.addEventListener("mouseup",    () => { isDown = false; });
    track.addEventListener("mousemove",  (e) => {
        if (!isDown) return;
        e.preventDefault();
        track.scrollLeft = scrollLeft - (e.pageX - track.offsetLeft - startX) * 1.6;
    });
    track.addEventListener("wheel", (e) => {
        if (e.deltaY !== 0) {
            e.preventDefault();
            track.scrollLeft += e.deltaY * 1.3;
        }
    }, { passive: false });
}


/* ─────────────────────────────────────────────────────────
   DELETE MODE
   ───────────────────────────────────────────────────────── */
let deleteMode = false;
const toggleBtn    = document.getElementById("toggle-delete-mode");
const selectAllBtn = document.getElementById("select-all-btn");
const deleteBtn    = document.getElementById("delete-selected-btn");
const cancelBtn    = document.getElementById("cancel-delete-mode");

toggleBtn?.addEventListener("click", () => {
    deleteMode = true;
    document.querySelectorAll(".delete-checkbox-wrapper").forEach(el => el.classList.remove("hidden"));
    toggleBtn.classList.add("hidden");
    selectAllBtn?.classList.remove("hidden");
    deleteBtn?.classList.remove("hidden");
    cancelBtn?.classList.remove("hidden");
});

cancelBtn?.addEventListener("click", () => {
    deleteMode = false;
    document.querySelectorAll(".delete-checkbox-wrapper").forEach(el => el.classList.add("hidden"));
    document.querySelectorAll(".delete-checkbox").forEach(cb => { cb.checked = false; });
    toggleBtn?.classList.remove("hidden");
    selectAllBtn?.classList.add("hidden");
    deleteBtn?.classList.add("hidden");
    cancelBtn?.classList.add("hidden");
});

selectAllBtn?.addEventListener("click", () => {
    const cbs = document.querySelectorAll(".delete-checkbox");
    const all = [...cbs].every(c => c.checked);
    cbs.forEach(c => { c.checked = !all; });
});

deleteBtn?.addEventListener("click", async () => {
    const ids = [...document.querySelectorAll(".delete-checkbox:checked")].map(c => c.dataset.id);
    if (!ids.length) {
        return Swal.fire({
            icon: "info",
            title: "Belum Ada Foto Dipilih",
            text: "Pilih minimal satu foto yang ingin dihapus.",
            background: "#17261f",
            color: "#f8fafc",
            confirmButtonColor: "#be123c"
        });
    }
    const res = await Swal.fire({
        title: `Hapus ${ids.length} Foto?`,
        text: "Kenangan ini akan dihapus permanen dari arsip.",
        icon: "warning", iconColor: "#e11d48",
        showCancelButton: true,
        confirmButtonColor: "#be123c", cancelButtonColor: "#475569",
        confirmButtonText: "Ya, Hapus!", cancelButtonText: "Batal",
        background: "#17261f", color: "#f8fafc",
        customClass: { popup: "rounded-[24px] border border-white/20" }
    });
    if (!res.isConfirmed) return;
    try {
        const resp = await fetch("/arsip/delete-multiple", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "X-CSRF-TOKEN": window.csrfToken || document.querySelector('meta[name="csrf-token"]')?.getAttribute("content")
            },
            body: JSON.stringify({ ids })
        });
        const data = await resp.json();
        if (data.success) {
            await Swal.fire({
                icon: "success", title: "Berhasil Dihapus",
                text: "Foto kenangan telah dihapus dari papan.",
                background: "#17261f", color: "#f8fafc",
                timer: 1500, showConfirmButton: false
            });
            location.reload();
        } else {
            Swal.fire({ icon: "error", title: "Gagal", text: data.message || "Terjadi kesalahan.", background: "#17261f", color: "#f8fafc" });
        }
    } catch {
        Swal.fire({ icon: "error", title: "Kesalahan Jaringan", background: "#17261f", color: "#f8fafc" });
    }
});

/* ─────────────────────────────────────────────────────────
   TOAST
   ───────────────────────────────────────────────────────── */
function showToast(msg, type = "success") {
    const c = document.getElementById("toast-container");
    if (!c) return;
    const t = document.createElement("div");
    t.className = `${type === "success" ? "bg-emerald-900/90 border-emerald-500/50" : "bg-rose-900/90 border-rose-500/50"} border text-white px-5 py-3 rounded-2xl shadow-xl flex items-center gap-3 transition-all duration-500 opacity-0 translate-y-4 backdrop-blur-md text-sm font-medium`;
    t.textContent = msg;
    c.appendChild(t);
    setTimeout(() => t.classList.remove("opacity-0", "translate-y-4"), 50);
    setTimeout(() => { t.classList.add("opacity-0"); setTimeout(() => t.remove(), 400); }, 3200);
}

/* ─────────────────────────────────────────────────────────
   BOOT
   ───────────────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", () => {
    renderArsip();
    // Also draw rope even when arsipData is empty
    if (!arsipData.length) requestAnimationFrame(drawRopeSVG);
});
